import urllib.request
for url in ['https://assemblyai.com/docs/api-reference/transcripts/submit','https://www.assemblyai.com/docs/llms.txt','https://raw.githubusercontent.com/AssemblyAI/assemblyai-python-sdk/master/README.md','https://api.assemblyai.com/v2/transcript','https://llm-gateway.assemblyai.com/v1/models']:
 try:
  r=urllib.request.urlopen(url,timeout=20)
  data=r.read().decode(); path='/tmp/aai-'+str(len(data))+'.txt';open(path,'w').write(data); print(url,r.status,path)
 except Exception as e: print(url,str(e))
PY"

